        for (let i = 0, len = ASSET_PROPERTIES.length; i < len; i++) {
            let asset = this[`_${ASSET_PROPERTIES[i]}`];
            if (asset) {
                if (!(asset instanceof Asset)) {
                    const id = parseInt(asset, 10);
                    if (id >= 0) {
                        asset = this.system.app.assets.get(asset);
