                                this._glPixelType,
                                mipObject
                            );
                        } else {
                            gl.texImage2D(
                                gl.TEXTURE_2D,
                                mipLevel,
                                this._glInternalFormat,
                                this._glFormat,
                                this._glPixelType,
                                mipObject
                            );

