                const vbOffset = (i * emitter.numParticleVerts + v) * (emitter.useMesh ? 6 : 4);
                let quadX = emitter.vbCPU[vbOffset];
                let quadY = emitter.vbCPU[vbOffset + 1];
                let quadZ = emitter.vbCPU[vbOffset + 2];
