        mesh.primitive[0].count = (this.numParticles * this.numParticleIndices);
        mesh.primitive[0].indexed = true;

        this.material = this._createMaterial();

        this.resetMaterial();

        this.meshInstance = new MeshInstance(mesh, this.material, this.node);
